  elseif($action==='card'){$id=(int)$_POST['card_id'];$status=$_POST['status'];if(!in_array($status,['active','blocked','cancelled'],true))throw new RuntimeException('Invalid card status.');$check=$pdo->prepare('SELECT a.branch_id FROM cards k JOIN accounts a ON a.account_id=k.account_id WHERE k.card_id=?');$check->execute([$id]);$br=$check->fetchColumn();if(!$br||($me['role']!=='Administrator'&&(int)$br!==(int)$me['branch_id']))throw new RuntimeException('Card is outside your branch.');$pdo->prepare('UPDATE cards SET status=? WHERE card_id=?')->execute([$status,$id]);audit('CARD_STATUS','cards',$id,'Card status set to '.$status);flash('Card status updated.');}
  elseif($action==='login_status'){$id=(int)$_POST['user_id'];$status=$_POST['status']==='active'?'active':'locked';$pdo->prepare('UPDATE users SET status=?,failed_login_attempts=0 WHERE user_id=?')->execute([$status,$id]);audit('LOGIN_STATUS','users',$id,'Login status set to '.$status);flash('Login status updated.');}
  elseif($action==='read_notification'){$id=(int)$_POST['notification_id'];$s=$pdo->prepare('UPDATE notifications SET is_read=1 WHERE notification_id=? AND user_id=?');$s->execute([$id,$me['id']]);flash('Notification marked as read.');}
  go('module.php?view='.rawurlencode($view));
 }catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();flash($ex instanceof RuntimeException?$ex->getMessage():'Action failed. Check the database record and try again.','err');go('module.php?view='.rawurlencode($view));}
